function toCamelKeys(row: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(row)) {
    out[key.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase())] = value;
  }
  return out;
}

console.log(toCamelKeys({ id: 1, customer_id: 7, total_kobo: 450000, note: null, placed_at_utc: "2026-09-20" }));

