function nairaToKobo(amount: string): number {
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(amount);
  if (!match) throw new RangeError(`not a naira amount: ${amount}`);
  const kobo = Number(match[1]) * 100 + Number((match[2] ?? "").padEnd(2, "0"));
  if (!Number.isSafeInteger(kobo)) throw new RangeError(`amount too large: ${amount}`);
  return kobo;
}

for (const a of ["1150.15", "12", "12.5", "0.07", "12.345", "abc"]) {
  try {
    console.log(a, nairaToKobo(a));
  } catch (error) {
    console.log(a, (error as Error).name);
  }
}

