type OrderStatus = "pending" | "paid" | "shipped" | "cancelled";
interface OrderRow {
  id: number;
  status: OrderStatus;
  note: string | null;
}

const STATUSES: readonly string[] = ["pending", "paid", "shipped", "cancelled"];

function isOrderRow(value: unknown): value is OrderRow {
  if (typeof value !== "object" || value === null) return false;
  const row = value as Record<string, unknown>;
  return (
    Number.isInteger(row.id) &&
    typeof row.status === "string" &&
    STATUSES.includes(row.status) &&
    "note" in row &&
    (row.note === null || typeof row.note === "string")
  );
}

const rows: unknown[] = [
  { id: 1, status: "paid", note: "Leave at the gate" },
  { id: 2, status: "refunded", note: null },
  { id: 3, status: "pending" },
  { id: 4.5, status: "paid", note: null },
  { id: 5, status: "shipped", note: null },
];
console.log(rows.filter(isOrderRow).map((r) => r.id));

