interface Column {
  name: string;
  udt: string;
  nullable: boolean;
}

const TYPES: Record<string, string> = { int4: "number", int8: "string", text: "string", timestamptz: "Date" };

function toInterface(table: string, columns: Column[]): string {
  const lines = columns.map((c) => `  ${c.name}: ${TYPES[c.udt] ?? "unknown"}${c.nullable ? " | null" : ""};`);
  return [`export interface ${table} {`, ...lines, "}"].join("\n");
}

