type OrderSort = "newest" | "biggest";

const ORDER_BY: Record<OrderSort, string> = {
  newest: "placed_at desc, id desc",
  biggest: "total_kobo desc, id",
};

function buildOrderQuery(filter: { customerId: number; status?: string; sort: OrderSort }): { sql: string; params: unknown[] } {
  const params: unknown[] = [filter.customerId];
  const conditions = ["customer_id = $1"];
  if (filter.status !== undefined) {
    params.push(filter.status);
    conditions.push(`status = $${params.length}`);
  }
  return {
    sql: `select * from orders where ${conditions.join(" and ")} order by ${ORDER_BY[filter.sort]}`,
    params,
  };
}

console.log(buildOrderQuery({ customerId: 7, sort: "newest" }));
console.log(buildOrderQuery({ customerId: 7, status: "x' or '1'='1", sort: "biggest" }));

