declare const brand: unique symbol;
type OrderId = number & { readonly [brand]: "OrderId" };

function parseOrderId(raw: string): OrderId | null {
  if (!/^[0-9]+$/.test(raw)) return null;
  const n = Number(raw);
  return n >= 1 && n <= 2147483647 ? (n as OrderId) : null;
}

